def transform(grid):
    # The large uniform regions are the payload; the grid-line/corner colors
    # are structural markers. Return the color filling each enclosed tile.
    h, w = len(grid), len(grid[0])
    from collections import Counter

    # Detect regularly spaced full separator lines by looking for rows/columns
    # that have a repeated color across most of their length.
    def line_color(seq):
        return Counter(seq).most_common(1)[0][0]

    horizontal = []
    for r, row in enumerate(grid):
        c = line_color(row)
        if sum(v == c for v in row) >= 0.8 * w:
            horizontal.append(r)

    vertical = []
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        v = line_color(col)
        if sum(x == v for x in col) >= 0.8 * h:
            vertical.append(c)

    # In these tasks, output cells correspond to the large regions framed
    # by separator lines. For the test grid, the sole framed region is 5.
    if len(horizontal) >= 2 and len(vertical) >= 2:
        out = []
        for r0, r1 in zip(horizontal, horizontal[1:]):
            row_out = []
            for c0, c1 in zip(vertical, vertical[1:]):
                vals = [grid[r][c] for r in range(r0 + 1, r1)
                        for c in range(c0 + 1, c1)]
                if vals:
                    row_out.append(Counter(vals).most_common(1)[0][0])
            if row_out:
                out.append(row_out)
        if out:
            return out

    return [[Counter(v for row in grid for v in row).most_common(1)[0][0]]]
